(window.EXSUB_C=window.EXSUB_C||{})[7]={"a-9":[{"t":"Elección del Presidente del Tribunal Constitucional (art. 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Elección del Presidente del Tribunal Constitucional (art. 9)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">en Pleno</mark> elige de entre sus miembros por <mark class=\"m-destacable\">votación secreta</mark> a su <mark class=\"m-autoridad\">Presidente</mark> y propone al <mark class=\"m-destacable\">Rey</mark> su nombramiento</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>En <mark class=\"m-plazo\">primera votación</mark> <mark class=\"m-accion\">se requerirá</mark> la <mark class=\"m-plazo\">mayoría absoluta</mark>. Si ésta no se alcanzase <mark class=\"m-accion\">se procederá</mark> a una <mark class=\"m-plazo\">segunda votación</mark>, en la que <mark class=\"m-accion\">resultará</mark> elegido quien obtuviese <mark class=\"m-plazo\">mayor número de votos</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>En caso de <mark class=\"m-destacable\">empate</mark> <mark class=\"m-accion\">se efectuará</mark> una última votación y si éste se repitiese, <mark class=\"m-accion\">será</mark> propuesto el de <mark class=\"m-destacable\">mayor antigüedad en el cargo</mark> y en caso de igualdad el de <mark class=\"m-destacable\">mayor edad</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>El nombre del elegido <mark class=\"m-accion\">se elevará</mark> al <mark class=\"m-destacable\">Rey</mark> para su nombramiento por un período de <mark class=\"m-plazo\">tres años</mark>, expirado el cual <mark class=\"m-accion\">podrá</mark> ser reelegido por <mark class=\"m-plazo\">una sola vez</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>El <mark class=\"m-autoridad\">Tribunal</mark> en Pleno <mark class=\"m-accion\">elegirá</mark> entre sus miembros, por el mismo procedimiento y por el mismo período de <mark class=\"m-plazo\">tres años</mark>, un <mark class=\"m-destacable\">Vicepresidente</mark>, al que incumbe sustituir al <mark class=\"m-autoridad\">Presidente</mark> en caso de vacante, ausencia u otro motivo legal y presidir la <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-destacable\">Segunda</mark></div></div></div>"}],"a-7":[{"t":"Quién preside cada órgano del Tribunal Constitucional (arts. 6 y 7)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Quién preside cada órgano del Tribunal Constitucional (arts. 6 y 7)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Pleno</h5><ul><li>Está integrado por <mark class=\"m-destacable\">todos los</mark> <mark class=\"m-autoridad\">Magistrados del Tribunal</mark></li><li>Lo preside el <mark class=\"m-autoridad\">Presidente</mark> y, en su defecto, el <mark class=\"m-destacable\">Vicepresidente</mark> y, a falta de ambos, el <mark class=\"m-autoridad\">Magistrado</mark> más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Sala</mark> Primera</h5><ul><li>Compuesta por <mark class=\"m-plazo\">seis</mark> <mark class=\"m-autoridad\">Magistrados</mark> nombrados por el <mark class=\"m-autoridad\">Tribunal</mark> en Pleno</li><li>La preside el <mark class=\"m-autoridad\">Presidente</mark> <mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Tribunal</mark> y, en su defecto, el <mark class=\"m-autoridad\">Magistrado</mark> más antiguo y, en caso de igual antigüedad, el de mayor edad</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Sala</mark> Segunda</h5><ul><li>Compuesta por <mark class=\"m-plazo\">seis</mark> <mark class=\"m-autoridad\">Magistrados</mark> nombrados por el <mark class=\"m-autoridad\">Tribunal</mark> en Pleno</li><li>La preside el <mark class=\"m-destacable\">Vicepresidente del</mark> <mark class=\"m-autoridad\">Tribunal</mark> y, en su defecto, el <mark class=\"m-autoridad\">Magistrado</mark> más antiguo y, en caso de igual antigüedad, el de mayor edad</li></ul></div></div></div>"}],"a-10":[{"t":"Competencias del Tribunal en Pleno (art. 10)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencias del Tribunal en Pleno (art. 10)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">en Pleno conoce de:</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\">Control de normas</mark><div class=\"vis-sub\"><span>De la constitucionalidad o inconstitucionalidad de los tratados internacionales</span><span>De los recursos de inconstitucionalidad contra las leyes y demás disposiciones con valor de ley, excepto los de mera aplicación de doctrina</span><span>De las cuestiones de constitucionalidad que reserve para sí; las demás <mark class=\"m-accion\">deberán deferirse</mark> a las <mark class=\"m-autoridad\">Salas</mark> según un turno objetivo</span><span>De los recursos previos de inconstitucionalidad contra Proyectos de Estatutos de Autonomía y contra Propuestas de Reforma de los Estatutos de Autonomía</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Conflictos</mark><div class=\"vis-sub\"><span>De los conflictos constitucionales de competencia entre el <mark class=\"m-autoridad\">Estado</mark> y las Comunidades Autónomas o de los de éstas entre sí</span><span>De los conflictos en defensa de la autonomía local</span><span>De los conflictos entre los <mark class=\"m-autoridad\">órganos</mark> constitucionales del <mark class=\"m-autoridad\">Estado</mark></span><span>De las anulaciones en defensa de la jurisdicción del <mark class=\"m-autoridad\">Tribunal</mark> previstas en el artículo 4.3</span></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Magistrados</mark> <mark class=\"m-destacable\">y</mark> <mark class=\"m-autoridad\">Tribunal</mark><div class=\"vis-sub\"><span>De la verificación del cumplimiento de los requisitos exigidos para el nombramiento de <mark class=\"m-autoridad\">Magistrado del Tribunal</mark> Constitucional</span><span>Del nombramiento de los <mark class=\"m-autoridad\">Magistrados</mark> que han de integrar cada una de las <mark class=\"m-autoridad\">Salas</mark></span><span>De la recusación de los <mark class=\"m-autoridad\">Magistrados del Tribunal</mark> Constitucional</span><span>De la aprobación y modificación de los reglamentos del <mark class=\"m-autoridad\">Tribunal</mark></span></div></div><div class=\"vis-rama\">De cualquier otro asunto que sea competencia del <mark class=\"m-autoridad\">Tribunal</mark> pero recabe para sí el Pleno, a propuesta del <mark class=\"m-autoridad\">Presidente</mark> o de <mark class=\"m-plazo\">tres</mark> <mark class=\"m-autoridad\">Magistrados</mark></div><div class=\"vis-rama\">En su <mark class=\"m-destacable\">autonomía como</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">constitucional</mark>, el Pleno elabora su presupuesto, que se integra como una <mark class=\"m-destacable\">sección independiente</mark> dentro de los Presupuestos Generales del <mark class=\"m-autoridad\">Estado</mark></div></div></div></div>"}],"a-14":[{"t":"Quórum de los acuerdos (art. 14)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Quórum de los acuerdos (art. 14)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Pleno</h5><ul><li>Puede adoptar acuerdos cuando estén presentes, al menos, <mark class=\"m-plazo\">dos tercios</mark> de los miembros que en cada momento lo compongan</li></ul></div><div class=\"vis-col\"><h5><mark class=\"m-autoridad\">Salas</mark></h5><ul><li>Los acuerdos de las <mark class=\"m-autoridad\">Salas</mark> <mark class=\"m-accion\">requerirán</mark> asimismo la presencia de <mark class=\"m-plazo\">dos tercios</mark> de los miembros que en cada momento las compongan</li></ul></div><div class=\"vis-col\"><h5>Secciones</h5><ul><li><mark class=\"m-accion\">Se requerirá</mark> la presencia de <mark class=\"m-plazo\">dos miembros</mark>, salvo que haya discrepancia, requiriéndose entonces la de sus <mark class=\"m-plazo\">tres miembros</mark></li></ul></div></div></div>"}],"a-15":[{"t":"Funciones del Presidente del Tribunal Constitucional (art. 15)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Funciones del Presidente del Tribunal Constitucional (art. 15)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Presidente</mark> <mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">Constitucional</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Ejerce la representación del <mark class=\"m-autoridad\">Tribunal,</mark> convoca y preside el <mark class=\"m-autoridad\">Tribunal</mark> en Pleno y convoca las <mark class=\"m-autoridad\">Salas</mark></div><div class=\"vis-rama\">Adopta las medidas precisas para el funcionamiento del <mark class=\"m-autoridad\">Tribunal,</mark> de las <mark class=\"m-autoridad\">Salas</mark> y de las Secciones</div><div class=\"vis-rama\">Comunica a las Cámaras, al <mark class=\"m-autoridad\">Gobierno</mark> o al <mark class=\"m-autoridad\">Consejo</mark> General del Poder Judicial, en cada caso, las vacantes</div><div class=\"vis-rama\">Nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral</div><div class=\"vis-rama\">Ejerce las potestades administrativas sobre el personal del <mark class=\"m-autoridad\">Tribunal</mark></div></div></div></div>"}],"a-32":[{"t":"Legitimados para el recurso de inconstitucionalidad (art. 32)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Legitimados para el recurso de inconstitucionalidad (art. 32)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Están legitimados para el recurso de inconstitucionalidad</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Contra Estatutos de Autonomía y demás Leyes del <mark class=\"m-autoridad\">Estado,</mark> normas con fuerza de ley, Tratados y Reglamentos de las Cámaras:<div class=\"vis-sub\"><span>El <mark class=\"m-autoridad\">Presidente</mark> <mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Gobierno</mark></span><span>El <mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-destacable\">del Pueblo</mark></span><span><mark class=\"m-plazo\">Cincuenta Diputados</mark></span><span><mark class=\"m-plazo\">Cincuenta Senadores</mark></span></div></div><div class=\"vis-rama\">Contra normas del <mark class=\"m-autoridad\">Estado</mark> que puedan afectar a su propio ámbito de autonomía:<div class=\"vis-sub\"><span>Los <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-destacable\">colegiados ejecutivos</mark> y las <mark class=\"m-destacable\">Asambleas de las Comunidades Autónomas</mark>, previo acuerdo adoptado al efecto</span></div></div></div></div></div>"}],"a-33":[{"t":"Plazo del recurso de inconstitucionalidad (art. 33)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Plazo del recurso de inconstitucionalidad (art. 33)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Supuesto</span><span>Plazo y requisitos</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">REGLA GENERAL</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">3 meses</span><div class=\"vt-t\">Dentro del plazo de <mark class=\"m-plazo\">tres meses</mark> a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado, mediante demanda presentada ante el <mark class=\"m-autoridad\">Tribunal</mark> Constitucional</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">EXCEPCIÓN: el <mark class=\"m-autoridad\">Presidente del Gobierno</mark> y los <mark class=\"m-autoridad\">órganos</mark> colegiados ejecutivos de las Comunidades Autónomas</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p v\">9 meses</span><div class=\"vt-t\"><mark class=\"m-accion\">Podrán interponer</mark> el recurso en el plazo de <mark class=\"m-plazo\">nueve meses</mark> si, con la finalidad de evitar su interposición, se cumplen los requisitos siguientes</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Que se reúna la <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-destacable\">Bilateral de Cooperación</mark> entre la Administración General del <mark class=\"m-autoridad\">Estado</mark> y la respectiva Comunidad Autónoma</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Que en el seno de la <mark class=\"m-autoridad\">Comisión</mark> Bilateral se haya adoptado un acuerdo sobre <mark class=\"m-destacable\">iniciación de negociaciones</mark> para resolver las discrepancias</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Que el acuerdo sea puesto en conocimiento del <mark class=\"m-autoridad\">Tribunal</mark> Constitucional dentro de los <mark class=\"m-plazo\">tres meses</mark> siguientes a la publicación, y se inserte en el «Boletín Oficial del <mark class=\"m-autoridad\">Estado»</mark> y en el «Diario Oficial» de la Comunidad Autónoma correspondiente</div></div></div></div></div></div>"}],"a-34":[{"t":"Tramitación del recurso de inconstitucionalidad (art. 34)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Tramitación del recurso de inconstitucionalidad (art. 34)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Personación y formulación de alegaciones (Congreso, Senado, <mark class=\"m-autoridad\">Gobierno</mark> por conducto del <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-destacable\">de Justicia</mark> y, si procede, <mark class=\"m-autoridad\">órganos</mark> autonómicos)</div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Plazo en el que el <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">dictará</mark> sentencia, transcurrido el de alegaciones</div><div class=\"vis-plazo\"><span class=\"n\">30 días</span>Máximo en ningún caso excedible, si el <mark class=\"m-autoridad\">Tribunal</mark> estima necesario, mediante <mark class=\"m-destacable\">resolución motivada</mark>, un plazo más amplio</div></div></div>"}],"a-35":[{"t":"Planteamiento de la cuestión de inconstitucionalidad por un Juez o Tribunal (art. 35)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Planteamiento de la cuestión de inconstitucionalidad por un Juez o Tribunal (art. 35)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>El <mark class=\"m-autoridad\">Juez o Tribunal,</mark> <mark class=\"m-destacable\">de oficio o a instancia de parte</mark>, considera que una norma con rango de Ley aplicable al caso y de cuya validez dependa el fallo pueda ser contraria a la Constitución</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>Solo puede plantearla una vez <mark class=\"m-destacable\">concluso el procedimiento</mark> y dentro del plazo para dictar sentencia, concretando la ley, el precepto constitucional que se supone infringido y en qué medida el fallo depende de la validez de la norma</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Oye a las partes y al <mark class=\"m-autoridad\">Ministerio Fiscal,</mark> en plazo común e improrrogable de <mark class=\"m-plazo\">10 días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>Seguidamente y sin más trámite, el <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-accion\">resolverá</mark> en el plazo de <mark class=\"m-plazo\">tres días</mark>. Dicho auto <u class=\"m-clave\">no</u> <mark class=\"m-accion\">será</mark> <u class=\"m-clave\">susceptible de recurso</u> de ninguna clase</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Se produce la <mark class=\"m-destacable\">suspensión provisional</mark> de las actuaciones hasta que el <mark class=\"m-autoridad\">Tribunal</mark> Constitucional se pronuncie sobre su admisión; producida ésta, el proceso permanece suspendido hasta que resuelva definitivamente</div></div></div>"}],"a-37":[{"t":"Cuestión de inconstitucionalidad ante el Tribunal Constitucional (art. 37)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Cuestión de inconstitucionalidad ante el Tribunal Constitucional (art. 37)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">Admisión</span><mark class=\"m-accion\">Podrá rechazarla</mark>, mediante <mark class=\"m-destacable\">auto</mark> y sin otra <mark class=\"m-autoridad\">audiencia</mark> que la del <mark class=\"m-autoridad\">Fiscal</mark> <mark class=\"m-destacable\">General del</mark> <mark class=\"m-autoridad\">Estado</mark>, si faltaren las condiciones procesales o fuere notoriamente infundada (decisión motivada)</div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Las partes del procedimiento judicial <mark class=\"m-accion\">podrán personarse</mark>, dentro de los 15 días siguientes a la publicación de la admisión en el BOE</div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Para formular alegaciones, en el plazo de otros 15 días (Congreso, Senado, <mark class=\"m-autoridad\">Fiscal</mark> General del <mark class=\"m-autoridad\">Estado, Gobierno y órganos</mark> autonómicos: plazo común improrrogable de quince días)</div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Concluido éste, el <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">dictará</mark> sentencia en el plazo de quince días</div><div class=\"vis-plazo\"><span class=\"n\">30 días</span>Máximo si estima necesario, mediante resolución motivada, un plazo más amplio</div></div></div>"}],"a-38":[{"t":"Efectos de las sentencias de inconstitucionalidad (arts. 38 a 40)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Efectos de las sentencias de inconstitucionalidad (arts. 38 a 40)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Sentencias en procedimientos de inconstitucionalidad</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-accion\">Tendrán</mark> el valor de cosa juzgada, <mark class=\"m-accion\">vincularán</mark> a todos los Poderes Públicos y <mark class=\"m-accion\">producirán</mark> efectos generales desde la fecha de su publicación en el «Boletín Oficial del <mark class=\"m-autoridad\">Estado»</mark></div><div class=\"vis-rama\">Las desestimatorias <mark class=\"m-accion\">impedirán</mark> cualquier planteamiento ulterior de la cuestión por cualquiera de las dos vías, fundado en la misma infracción de idéntico precepto constitucional</div><div class=\"vis-rama\">Si la sentencia declara la inconstitucionalidad, <mark class=\"m-accion\">declarará</mark> igualmente la nulidad de los preceptos impugnados y de los conexos</div><div class=\"vis-rama\"><mark class=\"m-accion\">No permitirán revisar</mark> procesos fenecidos mediante sentencia con fuerza de cosa juzgada, salvo en los procesos penales o contencioso-administrativos sancionadores en que resulte una reducción de la pena o de la sanción o una exclusión, exención o limitación de la responsabilidad</div></div></div></div>"}],"a-44":[{"t":"Recurso de amparo: según quién origine la violación (arts. 42 a 46)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Recurso de amparo: según quién origine la violación (arts. 42 a 46)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Origen de la violación</span><span>Plazo, requisitos y legitimados</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">DECISIONES O ACTOS SIN VALOR DE LEY DE LAS CORTES O DE LAS ASAMBLEAS DE LAS COMUNIDADES AUTÓNOMAS (art. 42)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">3 meses</span><div class=\"vt-t\"><mark class=\"m-accion\">Podrán</mark> ser recurridos dentro del plazo de <mark class=\"m-plazo\">tres meses</mark> desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Legitimados: la <mark class=\"m-destacable\">persona directamente afectada</mark>, el <mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-destacable\">del Pueblo</mark> y el <mark class=\"m-autoridad\">Ministerio Fiscal</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\"><mark class=\"m-autoridad\">GOBIERNO</mark> O SUS <mark class=\"m-autoridad\">AUTORIDADES</mark> O FUNCIONARIOS, U <mark class=\"m-autoridad\">ÓRGANOS</mark> EJECUTIVOS COLEGIADOS DE LAS COMUNIDADES AUTÓNOMAS (art. 43)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Una vez que se haya <mark class=\"m-destacable\">agotado la vía judicial</mark> procedente</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">20 días</span><div class=\"vt-t\">El plazo <mark class=\"m-accion\">será</mark> el de los <mark class=\"m-plazo\">veinte días</mark> siguientes a la notificación de la resolución recaída en el previo proceso judicial</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Legitimados: quienes hayan sido <mark class=\"m-destacable\">parte en el proceso judicial</mark> correspondiente, el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo y el <mark class=\"m-autoridad\">Ministerio Fiscal</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et n\">ACTO U OMISIÓN DE UN <mark class=\"m-autoridad\">ÓRGANO</mark> JUDICIAL (art. 44)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Que se hayan <mark class=\"m-destacable\">agotado todos los medios de impugnación</mark> previstos por las normas procesales para el caso concreto dentro de la vía judicial</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Que la violación sea imputable de modo <mark class=\"m-destacable\">inmediato y directo</mark> a una acción u omisión del <mark class=\"m-autoridad\">órgano</mark> judicial con independencia de los hechos que dieron lugar al proceso, acerca de los que, en ningún caso, <mark class=\"m-accion\">entrará</mark> a conocer el <mark class=\"m-autoridad\">Tribunal</mark> Constitucional</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Que se haya <mark class=\"m-destacable\">denunciado formalmente</mark> en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello</div></div><div class=\"vt-hoja\"><span class=\"vt-p n\">30 días</span><div class=\"vt-t\">El plazo para interponer el recurso de amparo <mark class=\"m-accion\">será</mark> de <mark class=\"m-plazo\">30 días</mark>, a partir de la notificación de la resolución recaída en el proceso judicial</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Legitimados: quienes hayan sido parte en el proceso judicial correspondiente, el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo y el <mark class=\"m-autoridad\">Ministerio Fiscal</mark></div></div></div></div></div></div>"}],"a-50":[{"t":"Tramitación del recurso de amparo (arts. 49 a 52)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Tramitación del recurso de amparo (arts. 49 a 52)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">49</span>Se inicia mediante <mark class=\"m-destacable\">demanda</mark> (hechos, preceptos constitucionales infringidos y amparo que se solicita), que <mark class=\"m-accion\">justificará</mark> la <mark class=\"m-destacable\">especial trascendencia constitucional</mark> del recurso. Defectos: las <mark class=\"m-destacable\">Secretarías de Justicia</mark> lo ponen de manifiesto en <mark class=\"m-plazo\">10 días</mark>, con apercibimiento de inadmisión</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">50</span>La <mark class=\"m-destacable\">Sección</mark>, por <mark class=\"m-destacable\">unanimidad</mark> de sus miembros, <mark class=\"m-accion\">acordará</mark> mediante <mark class=\"m-destacable\">providencia</mark> la admisión. Si no hay unanimidad, la Sección traslada la decisión a la <mark class=\"m-autoridad\">Sala</mark>. Inadmisión: providencia que especifica el requisito incumplido; solo recurrible en súplica por el <mark class=\"m-autoridad\">Ministerio Fiscal</mark> en <mark class=\"m-plazo\">tres días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">51</span>Admitida, la <mark class=\"m-autoridad\">Sala</mark> requiere con carácter urgente las actuaciones, en plazo que <mark class=\"m-accion\">no podrá exceder</mark> de <mark class=\"m-plazo\">diez días</mark>, y se emplaza a quienes fueron parte para comparecer en <mark class=\"m-plazo\">diez días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">52</span>Vista a quien promovió el amparo, a los personados, al <mark class=\"m-autoridad\">Abogado del Estado</mark> (si estuviera interesada la Administración Pública) y al <mark class=\"m-autoridad\">Ministerio Fiscal</mark>, por plazo común que <mark class=\"m-accion\">no podrá exceder</mark> de <mark class=\"m-plazo\">veinte días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">52</span>La <mark class=\"m-autoridad\">Sala</mark> o la Sección <mark class=\"m-accion\">pronunciará</mark> la <mark class=\"m-destacable\">sentencia</mark> en el plazo de <mark class=\"m-plazo\">10 días</mark> a partir del día señalado para la vista o deliberación</div></div></div>"}],"a-55":[{"t":"Sentencia de amparo (arts. 53 a 55)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Sentencia de amparo (arts. 53 a 55)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">La</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-destacable\">o la Sección</mark> <mark class=\"m-accion\">pronunciará</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\">Fallos (art. 53)</mark><div class=\"vis-sub\"><span>Otorgamiento de amparo</span><span>Denegación de amparo</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">La sentencia que otorgue el amparo</mark> <mark class=\"m-accion\">contendrá</mark> <mark class=\"m-destacable\">alguno o algunos de estos pronunciamientos (art. 55)</mark><div class=\"vis-sub\"><span>Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos</span><span>Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado</span><span>Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación</span></div></div><div class=\"vis-rama\">Si el recurso debiera ser estimado porque la ley aplicada lesione derechos fundamentales o libertades públicas, <mark class=\"m-accion\">se elevará</mark> la cuestión al <mark class=\"m-destacable\">Pleno</mark> con <mark class=\"m-destacable\">suspensión del plazo</mark> para dictar sentencia</div></div></div></div>"}],"a-56":[{"t":"Suspensión y medidas cautelares en el amparo (arts. 56 y 57)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Suspensión y medidas cautelares en el amparo (arts. 56 y 57)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Cuestión</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">REGLA GENERAL</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">La interposición del recurso de amparo <u class=\"m-clave\">no</u> <mark class=\"m-accion\">suspenderá</mark> los efectos del acto o sentencia impugnados</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">EXCEPCIÓN</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Cuando la ejecución produzca un perjuicio al recurrente que pudiera hacer perder al amparo su finalidad, la <mark class=\"m-autoridad\">Sala</mark> o la Sección, de oficio o a instancia del recurrente, <mark class=\"m-accion\">podrá disponer</mark> la <mark class=\"m-destacable\">suspensión, total o parcial</mark>, siempre y cuando <u class=\"m-clave\">no ocasione perturbación grave</u> a un interés constitucionalmente protegido, ni a los derechos fundamentales o libertades de otra persona</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et n\">PETICIÓN</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p n\">3 días</span><div class=\"vt-t\"><mark class=\"m-accion\">Podrá pedirse</mark> en cualquier tiempo, antes de haberse pronunciado la sentencia o decidirse el amparo de otro modo; el incidente se sustancia con <mark class=\"m-autoridad\">audiencia</mark> de las partes y del <mark class=\"m-autoridad\">Ministerio Fiscal,</mark> por un plazo común que <mark class=\"m-accion\">no excederá</mark> de <mark class=\"m-plazo\">tres días</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">URGENCIA EXCEPCIONAL</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">5 días</span><div class=\"vt-t\"><mark class=\"m-accion\">Se podrán adoptar</mark> en la resolución de admisión a trámite; <mark class=\"m-accion\">podrá</mark> ser impugnada en el plazo de <mark class=\"m-plazo\">cinco días</mark> desde su notificación, por el <mark class=\"m-autoridad\">Ministerio Fiscal</mark> y demás partes personadas; se resuelve mediante auto no susceptible de recurso alguno</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">MODIFICACIÓN (art. 57)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">La suspensión o su denegación puede ser modificada durante el curso del juicio, de oficio o a instancia de parte, en virtud de circunstancias <mark class=\"m-destacable\">sobrevenidas</mark> o que no pudieron ser conocidas al tiempo de sustanciarse el incidente</div></div></div></div></div></div>"}],"a-58":[{"t":"Indemnización por la suspensión en el amparo (art. 58)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Indemnización por la suspensión en el amparo (art. 58)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">Competentes</span>Los <mark class=\"m-autoridad\">Jueces</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-autoridad\">Tribunales</mark>, a cuya disposición <mark class=\"m-accion\">se pondrán</mark> las fianzas constituidas, para resolver sobre las peticiones de indemnización de los daños causados como consecuencia de la concesión o denegación de la suspensión</div><div class=\"vis-plazo\"><span class=\"n\">1 año</span>Plazo de presentación de las peticiones de indemnización, a partir de la publicación de la sentencia del <mark class=\"m-autoridad\">Tribunal</mark> Constitucional (se sustancian por el trámite de los incidentes)</div></div></div>"}],"c-3":[{"t":"Consentimiento de menores e incapaces (art. 3)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Consentimiento de menores e incapaces (art. 3)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span><mark class=\"m-accion\">Deberá prestarse</mark> <mark class=\"m-destacable\">por ellos mismos</mark> si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>En los restantes casos, mediante <mark class=\"m-destacable\">escrito por su representante legal</mark>, quien <mark class=\"m-accion\">estará</mark> obligado a poner en conocimiento previo del <mark class=\"m-autoridad\">Ministerio Fiscal</mark> el consentimiento proyectado</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Si en el plazo de <mark class=\"m-plazo\">ocho días</mark> el <mark class=\"m-autoridad\">Ministerio Fiscal</mark> se opusiere, <mark class=\"m-accion\">resolverá</mark> <mark class=\"m-destacable\">el</mark> <mark class=\"m-autoridad\">Juez</mark></div></div></div>"}],"c-4":[{"t":"Quién ejerce las acciones de protección de una persona fallecida (arts. 4 a 6)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Quién ejerce las acciones de protección de una persona fallecida (arts. 4 a 6)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1.º</span>Quien ésta haya <mark class=\"m-destacable\">designado en su testamento</mark> (la designación puede recaer en una persona jurídica)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2.º</span>No existiendo designación o habiendo fallecido la persona designada: el <mark class=\"m-destacable\">cónyuge, los descendientes, ascendientes y hermanos</mark> de la persona afectada que viviesen al tiempo de su fallecimiento</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3.º</span>A falta de todos ellos, el <mark class=\"m-autoridad\">Ministerio Fiscal</mark>, de oficio o a instancia de persona interesada, siempre que no hubieren transcurrido más de <mark class=\"m-plazo\">ochenta años</mark> desde el fallecimiento del afectado (el mismo plazo si es una persona jurídica designada en testamento)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso si\"><span class=\"et\">Víctimas</span>Delitos (art. 7.8): está legitimado el <mark class=\"m-destacable\">ofendido o perjudicado por el delito</mark>, haya o no ejercido la acción penal o civil, y en todo caso el <mark class=\"m-autoridad\">Ministerio Fiscal</mark></div></div></div>"}],"c-7":[{"t":"Intromisiones ilegítimas (art. 7)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Intromisiones ilegítimas (art. 7)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-accion\">Tendrán</mark> <mark class=\"m-destacable\">la consideración de intromisiones ilegítimas</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\">Medios de escucha, filmación y grabación</mark><div class=\"vis-sub\"><span>El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas</span><span>La utilización de aparatos de escucha, dispositivos ópticos, o de cualquier otro medio para el conocimiento de la vida íntima de las personas o de manifestaciones o cartas privadas no destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Divulgación y revelación</mark><div class=\"vis-sub\"><span>La divulgación de hechos relativos a la vida privada de una persona o familia que afecten a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo</span><span>La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quien los revela</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Imagen, nombre y voz</mark><div class=\"vis-sub\"><span>La captación, reproducción o publicación por fotografía, filme, o cualquier otro procedimiento, de la imagen de una persona en lugares o momentos de su vida privada o fuera de ellos</span><span>La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Dignidad</mark><div class=\"vis-sub\"><span>La imputación de hechos o la manifestación de juicios de valor a través de acciones o expresiones que de cualquier modo lesionen la dignidad de otra persona, menoscabando su fama o atentando contra su propia estimación</span><span>La utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga el menoscabo de la dignidad de las víctimas</span></div></div></div></div></div>"}],"c-8":[{"t":"Lo que no se reputa intromisión ilegítima (art. 8)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Lo que no se reputa intromisión ilegítima (art. 8)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Con carácter general</h5><ul><li>Las actuaciones <mark class=\"m-destacable\">autorizadas o acordadas por la</mark> <mark class=\"m-autoridad\">Autoridad</mark> <mark class=\"m-destacable\">competente</mark> de acuerdo con la ley</li><li>Cuando predomine un <mark class=\"m-destacable\">interés histórico, científico o cultural relevante</mark></li></ul></div><div class=\"vis-col\"><h5>El derecho a la propia imagen <mark class=\"m-accion\">no impedirá</mark></h5><ul><li>Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un <mark class=\"m-destacable\">cargo público</mark> o una profesión de <mark class=\"m-destacable\">notoriedad o proyección pública</mark> y la imagen se capte durante un acto público o en lugares abiertos al público</li><li>La utilización de la <mark class=\"m-destacable\">caricatura</mark> de dichas personas, de acuerdo con el uso social</li><li>La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como <mark class=\"m-destacable\">meramente accesoria</mark></li></ul></div><div class=\"vis-col\"><h5>Salvedad</h5><ul><li>Las excepciones de los párrafos a) y b) <u class=\"m-clave\">no</u> <mark class=\"m-accion\">serán</mark> <u class=\"m-clave\">de aplicación</u> respecto de las <mark class=\"m-autoridad\">autoridades</mark> o personas que desempeñen funciones que por su naturaleza necesiten el <mark class=\"m-destacable\">anonimato</mark> de la persona que las ejerza</li></ul></div></div></div>"}],"c-9":[{"t":"Tutela judicial frente a las intromisiones ilegítimas (art. 9)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Tutela judicial frente a las intromisiones ilegítimas (art. 9)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">La tutela judicial</mark> <mark class=\"m-accion\">comprenderá</mark> <mark class=\"m-destacable\">todas las medidas necesarias para poner fin a la intromisión ilegítima y, en particular, las necesarias para:</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">El restablecimiento del perjudicado en el pleno disfrute de sus derechos<div class=\"vis-sub\"><span>La declaración de la intromisión sufrida, el cese inmediato de la misma y la reposición del estado anterior</span><span>En el honor: sin perjuicio del derecho de réplica, la publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida</span></div></div><div class=\"vis-rama\">Prevenir intromisiones inminentes o ulteriores</div><div class=\"vis-rama\">La indemnización de los daños y perjuicios causados: la existencia de perjuicio <mark class=\"m-accion\">se presumirá</mark> siempre que se acredite la intromisión ilegítima, y <mark class=\"m-accion\">se extenderá</mark> al daño moral</div><div class=\"vis-rama\">La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos</div><div class=\"vis-rama\">Las acciones de protección <mark class=\"m-accion\">caducarán</mark> transcurridos <mark class=\"m-plazo\">cuatro años</mark> desde que el legitimado pudo ejercitarlas</div></div></div></div>"}],"a-2":[{"t":"El Tribunal Constitucional conocerá de… (art. 2)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>El Tribunal Constitucional conocerá de… (art. 2)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">Constitucional</mark> <mark class=\"m-accion\">conocerá</mark> <mark class=\"m-destacable\">en los casos y en la forma que esta Ley determina</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-destacable\">Normas</mark><div class=\"vis-sub\"><span>Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley</span><span>De la declaración sobre la constitucionalidad de los Tratados Internacionales</span><span>Del control previo de inconstitucionalidad en el supuesto previsto en la presente Ley</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Amparo y conflictos</mark><div class=\"vis-sub\"><span>Del recurso de amparo por violación de los derechos y libertades públicos</span><span>De los conflictos constitucionales de competencia entre el <mark class=\"m-autoridad\">Estado</mark> y las Comunidades Autónomas o de los de éstas entre sí</span><span>De los conflictos entre los <mark class=\"m-autoridad\">órganos</mark> constitucionales del <mark class=\"m-autoridad\">Estado</mark></span><span>De los conflictos en defensa de la autonomía local</span></div></div><div class=\"vis-rama\">De la verificación de los nombramientos de los <mark class=\"m-autoridad\">Magistrados del Tribunal</mark> Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</div><div class=\"vis-rama\">De las demás materias que le atribuyen la Constitución y las Leyes orgánicas</div><div class=\"vis-rama\"><mark class=\"m-accion\">Podrá dictar</mark> <mark class=\"m-destacable\">reglamentos</mark> sobre su propio funcionamiento y organización, aprobados por el <mark class=\"m-destacable\">Pleno</mark> y publicados en el BOE, autorizados por su <mark class=\"m-autoridad\">Presidente</mark></div></div></div></div>"}],"a-4":[{"t":"Defensa de la jurisdicción del Tribunal (art. 4)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Defensa de la jurisdicción del Tribunal (art. 4)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Jurisdicción del</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-destacable\">Constitucional</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><u class=\"m-clave\">En ningún caso</u> <mark class=\"m-accion\">se podrá promover</mark> cuestión de jurisdicción o competencia al <mark class=\"m-autoridad\">Tribunal</mark> Constitucional</div><div class=\"vis-rama\">El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">delimitará</mark> el ámbito de su jurisdicción y <mark class=\"m-accion\">adoptará</mark> cuantas medidas sean necesarias para preservarla, incluyendo la declaración de nulidad de aquellos actos o resoluciones que la menoscaben; <mark class=\"m-accion\">podrá apreciar</mark> <mark class=\"m-destacable\">de oficio o a instancia de parte</mark> su competencia o incompetencia</div><div class=\"vis-rama\">Sus resoluciones <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrán</mark> <u class=\"m-clave\">ser enjuiciadas</u> por ningún <mark class=\"m-autoridad\">órgano</mark> jurisdiccional del <mark class=\"m-autoridad\">Estado</mark></div><div class=\"vis-rama\">Si anula un acto o resolución que contravenga lo anterior, lo ha de hacer <mark class=\"m-destacable\">motivadamente</mark> y previa <mark class=\"m-autoridad\">audiencia</mark> al <mark class=\"m-autoridad\">Ministerio Fiscal</mark> y al <mark class=\"m-autoridad\">órgano</mark> autor del acto o resolución</div></div></div></div>"}],"a-27":[{"t":"Normas susceptibles de declaración de inconstitucionalidad (art. 27)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Normas susceptibles de declaración de inconstitucionalidad (art. 27)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Son susceptibles de declaración de inconstitucionalidad</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Los Estatutos de Autonomía y las demás Leyes orgánicas</div><div class=\"vis-rama\">Las demás Leyes, disposiciones normativas y actos del <mark class=\"m-autoridad\">Estado</mark> con fuerza de Ley</div><div class=\"vis-rama\">Los Tratados Internacionales</div><div class=\"vis-rama\">Los Reglamentos de las Cámaras y de las Cortes Generales</div><div class=\"vis-rama\">Las Leyes, actos y disposiciones normativas con fuerza de Ley de las Comunidades Autónomas</div><div class=\"vis-rama\">Los Reglamentos de las Asambleas legislativas de las Comunidades Autónomas</div></div></div></div>"}],"a-42":[{"t":"Amparo contra actos sin valor de Ley de las Cortes y Asambleas (art. 42)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Amparo contra actos sin valor de Ley de las Cortes y Asambleas (art. 42)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">3 meses</span>Las decisiones o actos sin valor de Ley, emanados de las Cortes o de cualquiera de sus <mark class=\"m-autoridad\">órganos,</mark> o de las Asambleas legislativas de las Comunidades Autónomas, o de sus <mark class=\"m-autoridad\">órganos,</mark> <mark class=\"m-accion\">podrán</mark> ser recurridos dentro del plazo de <mark class=\"m-plazo\">tres meses</mark> desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean <mark class=\"m-destacable\">firmes</mark></div></div></div>"}],"a-43":[{"t":"Amparo frente al Gobierno y sus autoridades (art. 43)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Amparo frente al Gobierno y sus autoridades (art. 43)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">Antes</span><mark class=\"m-accion\">Podrán</mark> dar lugar al recurso de amparo una vez que se haya <mark class=\"m-destacable\">agotado la vía judicial procedente</mark></div><div class=\"vis-plazo\"><span class=\"n\">20 días</span>El plazo para interponer el recurso de amparo constitucional <mark class=\"m-accion\">será</mark> el de los <mark class=\"m-plazo\">veinte días</mark> siguientes a la <mark class=\"m-destacable\">notificación</mark> de la resolución recaída en el previo proceso judicial</div><div class=\"vis-plazo\"><span class=\"n\">Fundamento</span>El recurso sólo <mark class=\"m-accion\">podrá fundarse</mark> en la infracción por una <mark class=\"m-destacable\">resolución firme</mark> de los preceptos constitucionales que reconocen los derechos o libertades susceptibles de amparo</div></div></div>"}],"a-49":[{"t":"La demanda de amparo (art. 49)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>La demanda de amparo (art. 49)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">Contenido</span><mark class=\"m-accion\">Se expondrán</mark> con claridad y concisión los hechos, <mark class=\"m-accion\">se citarán</mark> los preceptos constitucionales que se estimen infringidos y <mark class=\"m-accion\">se fijará</mark> con precisión el amparo que se solicita; la demanda <mark class=\"m-accion\">justificará</mark> la <mark class=\"m-destacable\">especial trascendencia constitucional</mark> del recurso</div><div class=\"vis-plazo\"><span class=\"n\">Se acompañan</span>El documento que acredite la representación del solicitante, la copia, traslado o certificación de la resolución recaída y tantas copias literales como partes en el previo proceso, y una más para el <mark class=\"m-autoridad\">Ministerio Fiscal</mark></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Si se incumplen los requisitos, las <mark class=\"m-destacable\">Secretarías de Justicia</mark> lo <mark class=\"m-accion\">pondrán</mark> de manifiesto al interesado en el plazo de <mark class=\"m-plazo\">10 días</mark>, con el apercibimiento de que, de no subsanarse el defecto, <mark class=\"m-accion\">se acordará</mark> la <mark class=\"m-destacable\">inadmisión</mark> del recurso</div></div></div>"}],"a-51":[{"t":"Requerimiento de las actuaciones (art. 51)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Requerimiento de las actuaciones (art. 51)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">10 días</span>La <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-accion\">requerirá</mark> con carácter urgente al <mark class=\"m-autoridad\">órgano o autoridad,</mark> o al <mark class=\"m-autoridad\">Juez o Tribunal,</mark> para que, en plazo que <mark class=\"m-accion\">no podrá exceder</mark> de <mark class=\"m-plazo\">diez días</mark>, remita las actuaciones o testimonio de ellas</div><div class=\"vis-plazo\"><span class=\"n\">10 días</span><mark class=\"m-accion\">Emplazará</mark> a quienes fueron parte en el procedimiento antecedente para que puedan comparecer en el proceso constitucional en el plazo de <mark class=\"m-plazo\">diez días</mark></div></div></div>"}],"a-52":[{"t":"Vista y sentencia en el amparo (art. 52)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Vista y sentencia en el amparo (art. 52)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">20 días</span>La <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-accion\">dará</mark> vista a quien promovió el amparo, a los personados, al <mark class=\"m-autoridad\">Abogado</mark> <mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Estado</mark> (si estuviera interesada la Administración Pública) y al <mark class=\"m-autoridad\">Ministerio Fiscal</mark>: plazo común que <mark class=\"m-accion\">no podrá exceder</mark> de <mark class=\"m-plazo\">veinte días</mark></div><div class=\"vis-plazo\"><span class=\"n\">Doctrina</span>La <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-accion\">podrá deferir</mark> la resolución a una de sus Secciones cuando sea aplicable <mark class=\"m-destacable\">doctrina consolidada</mark> del <mark class=\"m-autoridad\">Tribunal</mark> Constitucional, o señalar día para la vista, en su caso, o deliberación y votación</div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>La <mark class=\"m-autoridad\">Sala,</mark> o en su caso la Sección, <mark class=\"m-accion\">pronunciará</mark> la sentencia en el plazo de <mark class=\"m-plazo\">10 días</mark> a partir del día señalado para la vista o deliberación</div></div></div>"}]};